css:
.schedule-heading {
    text-align: center;
    margin-bottom: 16px;
}

.schedule-heading h2 {
    margin: 0;
    font-size: 18pt;
}

.schedule-heading p {
    margin: 6px 0 0;
    color: #555;
    font-size: 9.5pt;
}

.schedule-table {
    width: 100%;
    border: 1px solid #ddd;
    border-spacing: 0;
    border-collapse: separate;
    border-radius: 8px;
    overflow: hidden;
    table-layout: fixed;
}

.schedule-table th,
.schedule-table td {
    padding: 7px 8px;
    vertical-align: top;
    font-size: 9pt;
    line-height: 1.4;
    word-wrap: break-word;
}

.schedule-table th {
    background-color: #f5f5f5;
    border-right: 1px solid #ddd;
    border-bottom: 1px solid #ddd;
    font-weight: 600;
    text-align: left;
}

.schedule-table td {
    border-right: 1px solid #ddd;
    border-bottom: 1px solid #ddd;
}

.schedule-table th:last-child,
.schedule-table td:last-child {
    border-right: none;
}

.schedule-table tbody tr:last-child td {
    border-bottom: none;
}

.schedule-table tbody tr.data-row:nth-child(odd) td {
    background-color: #fafafa;
}

.schedule-table tr {
    page-break-inside: avoid;
}

.schedule-table thead {
    display: table-header-group;
}

.code-col {
    width: 7%;
    white-space: nowrap;
}

.desc-col {
    width: 41%;
}

.sanction-col {
    width: 13%;
}

.category-row td {
    background-color: #f0f0f0 !important;
    border-bottom: 1px solid #b40000;
    font-weight: 700;
    text-align: center;
    padding: 8px;
}

.preserve-lines {
    white-space: pre-line;
}

@media print {
    @page {
        size: A4 landscape;
        margin: 12mm;
    }

    @page {
        @bottom-right {
            content: "Page " counter(page) " of " counter(pages);
            font-size: 9pt;
            color: #999;
        }
    }
}
